package com.alsafa.native4.core;
import android.content.ContentValues;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import com.alsafa.native4.sync.SyncOperation;import org.json.JSONArray;import org.json.JSONObject;import java.util.ArrayList;import java.util.List;import java.util.UUID;
/** Direct quick-repair sale. Several parts + one service fee + split payments are one atomic customer operation. */
public final class DirectRepairPartSaleStore {private final CoreStore.DbProvider provider;private final String deviceId;public DirectRepairPartSaleStore(CoreStore.DbProvider provider,String deviceId){this.provider=provider;this.deviceId=deviceId;}
 public static final class Line{public final String partId;public final int quantity;public final double unitPrice;public Line(String id,int q,double p){partId=req(id,"قطعة الصيانة");if(q<=0)throw new IllegalArgumentException("الكمية يجب أن تكون أكبر من صفر");if(!Double.isFinite(p)||p<0)throw new IllegalArgumentException("سعر القطعة غير صالح");quantity=q;unitPrice=p;}}
 public Result sell(String partId,int quantity,double unitPrice,double serviceFee,String currency,String paymentMethod)throws Exception{String cur=currency(currency),pay=req(paymentMethod,"طريقة الدفع").toUpperCase();List<SplitPaymentStore.Payment> legs=new ArrayList<>();double total=unitPrice*quantity+serviceFee;if(total>0&&!"LATER".equals(pay))legs.add(new SplitPaymentStore.Payment(total,cur,pay,drawer(pay)));return sellSplit(partId,quantity,unitPrice,serviceFee,cur,legs);}
 public Result sellSplit(String partId,int quantity,double unitPrice,double serviceFee,String invoiceCurrency,List<SplitPaymentStore.Payment> payments)throws Exception{ArrayList<Line> lines=new ArrayList<>();lines.add(new Line(partId,quantity,unitPrice));return sellMulti(lines,serviceFee,invoiceCurrency,payments);}
 public Result sellMulti(List<Line> input,double serviceFee,String invoiceCurrency,List<SplitPaymentStore.Payment> payments)throws Exception{if(input==null||input.isEmpty())throw new IllegalArgumentException("اختر قطعة صيانة واحدة على الأقل");if(!Double.isFinite(serviceFee)||serviceFee<0)throw new IllegalArgumentException("أجرة الخدمة غير صالحة");String cur=currency(invoiceCurrency);java.util.LinkedHashMap<String,Line> merged=new java.util.LinkedHashMap<>();for(Line x:input){Line old=merged.get(x.partId);if(old==null)merged.put(x.partId,x);else{if(Math.abs(old.unitPrice-x.unitPrice)>0.000001)throw new IllegalArgumentException("تم تكرار نفس القطعة بسعرين مختلفين");merged.put(x.partId,new Line(x.partId,old.quantity+x.quantity,x.unitPrice));}}SQLiteDatabase db=provider.db();db.beginTransaction();try{long now=System.currentTimeMillis();String saleId="partsale-"+UUID.randomUUID();JSONArray linesJson=new JSONArray();double partsTotal=0,totalCost=0;String firstName="";for(Line x:merged.values()){String name;int before;double cost;try(Cursor c=db.rawQuery("SELECT name,quantity,unit_cost FROM repair_inventory WHERE part_id=? AND deleted_at IS NULL",new String[]{x.partId})){if(!c.moveToFirst())throw new IllegalArgumentException("قطعة الصيانة غير موجودة: "+x.partId);name=c.getString(0);before=c.getInt(1);cost=c.getDouble(2);}if(before<x.quantity)throw new IllegalArgumentException("رصيد قطعة الصيانة غير كافٍ: "+name);int after=before-x.quantity;ContentValues p=new ContentValues();p.put("quantity",after);p.put("updated_at",now);if(db.update("repair_inventory",p,"part_id=? AND deleted_at IS NULL",new String[]{x.partId})!=1)throw new IllegalStateException("تعذر تحديث رصيد قطعة الصيانة");ContentValues mv=new ContentValues();mv.put("move_id",saleId+"-stock-"+x.partId);mv.put("part_id",x.partId);mv.put("source_type","DIRECT_SALE");mv.put("source_id",saleId);mv.put("before_qty",before);mv.put("delta_qty",-x.quantity);mv.put("after_qty",after);mv.put("created_at",now);db.insertOrThrow("repair_inventory_moves",null,mv);double lineTotal=x.unitPrice*x.quantity;partsTotal+=lineTotal;totalCost+=cost*x.quantity;if(firstName.isEmpty())firstName=name;linesJson.put(new JSONObject().put("partId",x.partId).put("partName",name).put("quantity",x.quantity).put("beforeQty",before).put("afterQty",after).put("unitCost",cost).put("unitPrice",x.unitPrice).put("lineTotal",lineTotal));}double total=partsTotal+serviceFee;FxSnapshotStore.Snapshot fx=FxSnapshotStore.capture(db,"REPAIR_PART_DIRECT",saleId,cur,total,now);JSONArray paymentJson=new JSONArray();if(payments!=null&&!payments.isEmpty())paymentJson=SplitPaymentStore.write(db,"REPAIR_PART_DIRECT",saleId,payments,now);double paidUsd=0;for(int i=0;i<paymentJson.length();i++)paidUsd+=paymentJson.getJSONObject(i).getDouble("usdAmount");if(paidUsd-fx.usdAmount>0.01)throw new IllegalArgumentException("مجموع الدفعات أكبر من قيمة البيع بعد تحويل العملات");JSONObject j=new JSONObject().put("saleId",saleId).put("saleType","REPAIR_PART_DIRECT").put("lines",linesJson).put("lineCount",linesJson.length()).put("partsTotal",partsTotal).put("partsCost",totalCost).put("serviceFee",serviceFee).put("total",total).put("currency",cur).put("payments",paymentJson).put("paidUsdSnapshot",paidUsd).put("balanceUsdSnapshot",Math.max(0,fx.usdAmount-paidUsd)).put("fxUsdPerUnit",fx.usdPerUnit).put("totalUsdSnapshot",fx.usdAmount).put("createdAt",now);provider.enqueue(db,SyncOperation.create(SyncOperation.Kind.SALE_CREATE,saleId,j.toString(),deviceId));db.setTransactionSuccessful();return new Result(saleId,linesJson.length()==1?firstName:linesJson.length()+" قطع",0,0,total,fx.usdAmount,cur,paymentJson.length(),paidUsd,Math.max(0,fx.usdAmount-paidUsd));}finally{db.endTransaction();}}
 private static String drawer(String pay){if("SHAM_CASH".equals(pay))return "SHAM_CASH";if("BANK".equals(pay))return "BANK";if("EXTERNAL".equals(pay))return "EXTERNAL";return "MAIN";}private static String req(String v,String l){String s=trim(v);if(s.isEmpty())throw new IllegalArgumentException(l+" مطلوب");return s;}private static String trim(String v){return v==null?"":v.trim();}private static String currency(String v){String x=trim(v).toUpperCase();return x.equals("TRY")||x.equals("SYP")?x:"USD";}
 public static final class Result{public final String saleId,partName,currency;public final int beforeQty,remainingQty,paymentCount;public final double total,totalUsd,paidUsd,balanceUsd;Result(String id,String n,int b,int r,double t,double u,String c,int pc,double pu,double bu){saleId=id;partName=n;beforeQty=b;remainingQty=r;total=t;totalUsd=u;currency=c;paymentCount=pc;paidUsd=pu;balanceUsd=bu;}}
}
